def _upgrade_notice() -> None:
    policies = sa.table(
        "policy_versions",
        sa.column("id", sa.Uuid()),
        sa.column("policy_type", sa.String()),
        sa.column("version", sa.String()),
        sa.column("text", sa.String()),
        sa.column("current", sa.Boolean()),
        sa.column("created_at", sa.DateTime(timezone=True)),
    )
    bind = op.get_bind()
    old_text: str = bind.execute(
        sa.select(policies.c.text).where(
            policies.c.policy_type == "PRIVACY_NOTICE",
            policies.c.version == "2026-11-11",
        )
    ).scalar_one()
    text = old_text.replace(
        "No external processor or international transfer is enabled by this foundation.",
        "Requested official/public lookups send only address queries to GRAR and selected "
        "building geometry to Agentschap Onroerend Erfgoed; no account identity or documents "
        "are sent. Provider roles and any applicable transfer safeguards require review.",
    ) + (
        " Milestone 2: official property identifiers, source observations, query/refresh history "
        "and attribution are retained with your private workspace and included in export/deletion. "
        "Government sources may act in their own controller capacity; "
        "no blanket DPA or lawful-basis conclusion is implied. Production public lookups "
        "require explicit operational privacy review."
    )
    bind.execute(
        sa.update(policies).where(policies.c.policy_type == "PRIVACY_NOTICE").values(current=False)
    )
    existing = bind.execute(
        sa.select(policies.c.id).where(
            policies.c.policy_type == "PRIVACY_NOTICE",
            policies.c.version == "2026-11-11-m2",
        )
    ).scalar_one_or_none()
    if existing is None:
        bind.execute(
            sa.insert(policies).values(
                id=uuid4(),
                policy_type="PRIVACY_NOTICE",
                version="2026-11-11-m2",
                text=text,
                current=True,
                created_at=datetime.now(UTC),
            )
        )
    else:
        bind.execute(sa.update(policies).where(policies.c.id == existing).values(current=True))


